def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            version_part, _ = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release (everything after '-' that's part of pre-release)
        if '-' in version_part:
            base_part, prerelease = version_part.split('-', 1)
            prerelease_ids = prerelease.split('.')
        else:
            base_part = version_part
            prerelease_ids = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        return (major, minor, patch, prerelease_ids)

    def prerelease_sort_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1, [])

        # Pre-release present, sorts before no pre-release
        key_parts = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers: numeric comparison, sorts before non-numeric
                key_parts.append((0, int(identifier)))
            else:
                # Non-numeric identifiers: ASCII order, sorts after numeric
                key_parts.append((1, identifier))

        return (0, key_parts)

    # Create list of (sort_key, original_index, version_string)
    indexed_versions = []
    for idx, v in enumerate(versions):
        major, minor, patch, prerelease_ids = parse_version(v)
        sort_key = (major, minor, patch, prerelease_sort_key(prerelease_ids))
        indexed_versions.append((sort_key, idx, v))

    # Sort by sort_key, then by original index for stability
    indexed_versions.sort(key=lambda x: (x[0], x[1]))

    # Return just the version strings
    return [v for _, _, v in indexed_versions]

